    @Test
    void holyWeekIsHighSeasonIn2027() {
        // Easter 2027 is March 28; Holy Week is March 21-28 (Palm Sunday through Easter)
        LocalDate palmSunday = LocalDate.of(2027, 3, 21);
        LocalDate easterSunday = LocalDate.of(2027, 3, 28);

        assertTrue(PriceCalculator.isHighSeason(palmSunday));
        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 25)));
        assertTrue(PriceCalculator.isHighSeason(easterSunday));

        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 20)));
        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 3, 29)));
    }

    @Test
    void holyWeekIsHighSeasonIn2028() {
        // Easter 2028 is April 16; Holy Week is April 9-16 (Palm Sunday through Easter)
        LocalDate palmSunday = LocalDate.of(2028, 4, 9);
        LocalDate easterSunday = LocalDate.of(2028, 4, 16);

        assertTrue(PriceCalculator.isHighSeason(palmSunday));
        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 13)));
        assertTrue(PriceCalculator.isHighSeason(easterSunday));

        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 8)));
        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2028, 4, 17)));
    }

    @Test
    void holyWeekPriceIncrease() {
        Price price = calculator.calculate(
                standardRoom, LocalDate.of(2027, 3, 20), LocalDate.of(2027, 3, 22), RatePlan.STANDARD);

        // March 20 (low season): 249.90; March 21 (Palm Sunday, high season): 312.38
        assertEquals(new BigDecimal("562.28"), price.total());
    }
}

